UPDATE SYT0YS
   SET GYULJE_YMD   = TO_DATE(REPLACE(#{gyuljeYmd, jdbcType=VARCHAR}, '-', ''), 'YYYYMMDD')
     , GYULJE_GB    = #{gyuljeGb, jdbcType=VARCHAR}
     , GYULJE_JM_CD = #{gyuljeJmCd, jdbcType=VARCHAR}
     , SURY_AEK     = #{suryAek, jdbcType=NUMERIC}
     , BUNHAL_AEK   = #{bunhalAek, jdbcType=NUMERIC}
 WHERE CORP_GR  = #{corpGr, jdbcType=VARCHAR}
   AND YMD      = TO_DATE(REPLACE(#{ymd, jdbcType=VARCHAR}, '-', ''), 'YYYYMMDD')
   AND TR_YMD   = TO_DATE(REPLACE(#{trYmd, jdbcType=VARCHAR}, '-', ''), 'YYYYMMDD')
   AND TR_CD    = #{trCd, jdbcType=VARCHAR}
   AND FUND_CD  = #{fundCd, jdbcType=VARCHAR}
   AND TR_CO_CD = #{trCoCd, jdbcType=VARCHAR}
   AND TRUSTEE  = #{trustee, jdbcType=VARCHAR}
   AND JM_CD    = #{jmCd, jdbcType=VARCHAR}
   AND TR_SEQ   = #{trSeq, jdbcType=NUMERIC}
   AND BS_TYPE  = #{bsType, jdbcType=NUMERIC}
